    g_healthBars.addHealthBackground(bar.path, bar.offsetX, bar.offsetY, bar.barOffsetX, bar.barOffsetY, bar.height)
  end
  for _, bar in ipairs(manaBars) do
    g_healthBars.addManaBackground(bar.path, bar.offsetX, bar.offsetY, bar.barOffsetX, bar.barOffsetY, bar.height)
